// 关卡 01 · 一次往返
//
// 这里没有网络请求。nextReply() 从 transcript.go 里一段写死的脚本取出
// 模型的下一条回复,于是唯一被考察的东西就是循环的形状。
package main

import "fmt"

func main() {
	msgs := []message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: "统计这个目录里有几个 .go 文件"},
	}

	for turn := 1; turn <= maxTurns; turn++ {
		reply := nextReply(msgs)
		fmt.Printf("--- 第 %d 轮 ---\n", turn)

		// 助手这一轮要原样回写。它带着 tool_calls,下一轮的结果得靠它配对。
		[[1]]

		if reply.Content != "" {
			fmt.Printf("模型说: %s\n", reply.Content)
		}

		// 这一轮到此为止了吗
		if [[2]] {
			break
		}

		for _, call := range reply.ToolCalls {
			output := fakeBash(call.Command)
			fmt.Printf("  $ %s\n  | %s\n", call.Command, output)

			// 每一个 tool_call 都必须有一条结果回去。
			[[3]]
		}
	}

	fmt.Println()
	fmt.Println("--- 消息数组 ---")
	for i, m := range msgs {
		fmt.Printf("%d %-9s %s\n", i, m.Role, summarize(m))
	}
}

package main

// 这一关不联网。下面这段脚本就是"模型":它只看消息数组的最后一条是什么,
// 于是循环里的每一处改动都会立刻反映在它看到的东西上。

const systemPrompt = "你是一个在终端里干活的编码 agent,只有一个工具:bash。"

// 一个保险丝。没有它,一个不停要工具的模型会一直跑到你的额度见底。
const maxTurns = 25

type message struct {
	Role      string
	Content   string
	ToolCalls []toolCall

	// 只在 role:"tool" 的消息上出现,它把一条结果和要它的那次调用配起来。
	ToolCallID string
}

type toolCall struct {
	ID      string
	Command string
}

func nextReply(msgs []message) message {
	if msgs[len(msgs)-1].Role == "tool" {
		return message{Role: "assistant", Content: "这个目录里有 3 个 .go 文件。"}
	}
	return message{
		Role:      "assistant",
		ToolCalls: []toolCall{{ID: "call_1", Command: "ls *.go | wc -l"}},
	}
}

// fakeBash 站在 exec.Command 的位置上。真实的 stage 00 在这里起一个进程。
func fakeBash(command string) string {
	if command == "ls *.go | wc -l" {
		return "3"
	}
	return "[no output]"
}

func summarize(m message) string {
	if len(m.ToolCalls) > 0 {
		return "tool_calls: " + m.ToolCalls[0].Command
	}
	if m.ToolCallID != "" {
		return m.ToolCallID + " -> " + m.Content
	}
	r := []rune(m.Content)
	if len(r) > 24 {
		return string(r[:24]) + "..."
	}
	return m.Content
}
